package com.hybridrag;

import com.fasterxml.jackson.databind.JsonNode;
import com.hybridrag.model.QueryRecord;
import com.hybridrag.service.*;
import javafx.application.Application;
import javafx.application.Platform;
import javafx.collections.*;
import javafx.concurrent.Task;
import javafx.geometry.Insets;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.layout.*;
import javafx.stage.FileChooser;
import javafx.stage.Stage;
import java.io.File;
import java.time.LocalDateTime;
import java.util.*;

public class App extends Application {
 private final BorderPane root=new BorderPane(); private final VBox sidebar=new VBox(8); private final StackPane content=new StackPane(); private final ObservableList<QueryRecord> history=FXCollections.observableArrayList(); private final QueryService queries=new QueryService(); private final ApiService api=new ApiService(); private Label backendBadge; private Label dashboardStatusValue; private String selectedDataset="Default Dataset"; private String databaseSummary="No local replacement configuration";
 @Override public void start(Stage stage){stage.setTitle("Hybrid GraphRAG | Text-to-SQL Intelligence Platform"); stage.setMinWidth(980);stage.setMinHeight(650); root.setLeft(buildSidebar());root.setCenter(content); showDashboard(); Scene scene=new Scene(root,1200,750); scene.getStylesheets().add(getClass().getResource("/dark.css").toExternalForm());stage.setScene(scene);stage.show(); refreshBackendStatus();}
 private VBox buildSidebar(){sidebar.getStyleClass().add("sidebar");sidebar.setPrefWidth(225);Label brand=new Label("*  Hybrid GraphRAG");brand.setStyle("-fx-font-size:18px;-fx-font-weight:bold;-fx-text-fill:#38BDF8;");Label sub=new Label("TEXT-TO-SQL PLATFORM");sub.getStyleClass().add("subtitle");sidebar.getChildren().addAll(brand,sub,new Separator()); for(String name:List.of("Dashboard","Ask Database","Schema","Graph","Query History","Data Sources","Settings")){Button b=new Button(name);b.setMaxWidth(Double.MAX_VALUE);b.getStyleClass().add("nav-button");b.setOnAction(e->{selectNav(b);switch(name){case "Dashboard"->showDashboard();case "Ask Database"->showAsk();case "Schema"->showUnavailable("Schema","The backend does not currently expose a schema HTTP endpoint.");case "Graph"->showUnavailable("Graph","Graph data unavailable from backend. No graph HTTP endpoint is currently defined.");case "Query History"->showHistory();case "Data Sources"->showDataSources();case "Settings"->showSettings();}});sidebar.getChildren().add(b);} Region spacer=new Region();VBox.setVgrow(spacer,Priority.ALWAYS); backendBadge=new Label("* Checking backend...");backendBadge.getStyleClass().add("muted");sidebar.getChildren().addAll(spacer,new Separator(),backendBadge);return sidebar;}
 private void selectNav(Button selected){for(var n:sidebar.getChildren())if(n instanceof Button b)b.getStyleClass().remove("nav-active");selected.getStyleClass().add("nav-active");}
 private VBox page(String title,String description){VBox box=new VBox(18);box.setPadding(new Insets(30));Label h=new Label(title);h.getStyleClass().add("title");Label d=new Label(description);d.getStyleClass().add("subtitle");box.getChildren().addAll(h,d);return box;}
 private VBox card(String title,String value,String note){VBox b=new VBox(8);b.getStyleClass().add("card");Label t=new Label(title);t.getStyleClass().add("subtitle");Label v=new Label(value);v.setStyle("-fx-font-size:22px;-fx-font-weight:bold;");Label n=new Label(note);n.getStyleClass().add("muted");b.getChildren().addAll(t,v,n);return b;}
 private void showDashboard(){VBox p=page("Dashboard","Live overview of your Hybrid GraphRAG backend.");GridPane g=new GridPane();g.setHgap(14);g.setVgap(14);backendBadge=new Label("* Checking backend...");VBox backendCard=card("Backend Status","Checking...","GET /"); dashboardStatusValue=(Label)backendCard.getChildren().get(1); g.add(backendCard,0,0);g.add(card("Database Status","N/A","Not exposed by the API"),1,0);g.add(card("Graph Status","N/A","No graph status route"),2,0);g.add(card("Tables","N/A","Schema route not exposed"),0,1);g.add(card("Queries Executed",String.valueOf(history.size()),"This session"),1,1);g.add(card("API routes","GET /  |  POST /query","Discovered in backend/main.py"),2,1);p.getChildren().add(g);Label note=new Label("The query endpoint executes generated SQL and returns results. Schema and graph endpoints are not currently implemented by the backend.");note.getStyleClass().add("muted");note.setWrapText(true);p.getChildren().add(note);content.getChildren().setAll(new ScrollPane(p)); refreshBackendStatus();}
 private void refreshBackendStatus(){if(backendBadge==null)return;Label target=backendBadge;runTask(()->api.get("/"),n->{target.setText("* Connected");target.setStyle("-fx-text-fill:#22C55E;");if(dashboardStatusValue!=null)dashboardStatusValue.setText("Connected");},e->{target.setText("* Offline");target.setStyle("-fx-text-fill:#EF4444;");if(dashboardStatusValue!=null)dashboardStatusValue.setText("Offline");});}
 private void showAsk(){VBox p=page("Ask Database","Ask a question in natural language. SQL and rows come from the live backend.");TextArea question=new TextArea();question.setPromptText("Ask a question about your database...\nExample: Which customers placed the most orders?");question.setPrefRowCount(4);TextArea sql=new TextArea();sql.setPromptText("Generated SQL will appear here");sql.setEditable(false);sql.setPrefRowCount(4);TableView<Map<String,String>> table=new TableView<>();table.setPlaceholder(new Label("Query results will appear here"));Label status=new Label("Ready");status.getStyleClass().add("muted");Label details=new Label("Retrieval details are not currently exposed by the backend.");details.getStyleClass().add("muted");Button generate=new Button("Generate SQL");Button clear=new Button("Clear");clear.getStyleClass().add("button secondary");generate.setOnAction(e->{String q=question.getText().trim();if(q.isEmpty()){status.setText("Enter a question first.");return;}generate.setDisable(true);status.setText("Loading... Calling POST /query");long start=System.nanoTime();Task<JsonNode> task=new Task<>(){protected JsonNode call()throws Exception{return queries.ask(q);}};task.setOnSucceeded(ev->{generate.setDisable(false);JsonNode r=task.getValue();String querySql=r.path("sql").asText("");sql.setText(querySql);populateTable(table,r);String elapsed=String.format(Locale.ROOT,"%.2f s",(System.nanoTime()-start)/1e9);status.setText("Executed successfully | "+elapsed);history.add(0,new QueryRecord(q,querySql,"Success",elapsed,LocalDateTime.now()));});task.setOnFailed(ev->{generate.setDisable(false);String message=message(task.getException());status.setText("Request failed: "+message);history.add(0,new QueryRecord(q,"","Failed",String.format(Locale.ROOT,"%.2f s",(System.nanoTime()-start)/1e9),LocalDateTime.now()));});Thread t=new Thread(task,"backend-query");t.setDaemon(true);t.start();});clear.setOnAction(e->{question.clear();sql.clear();table.getItems().clear();table.getColumns().clear();status.setText("Ready");});HBox buttons=new HBox(10,generate,clear);p.getChildren().addAll(label("Question"),question,buttons,label("Generated SQL"),sql,status,label("Results"),table,details);VBox.setVgrow(table,Priority.ALWAYS);content.getChildren().setAll(new ScrollPane(p));}
 private Label label(String s){Label l=new Label(s);l.setStyle("-fx-font-weight:bold;");return l;}
 private void populateTable(TableView<Map<String,String>> t,JsonNode response){t.getColumns().clear();t.getItems().clear();JsonNode cols=response.path("columns");if(cols.isArray())for(JsonNode c:cols){String name=c.asText();TableColumn<Map<String,String>,String> column=new TableColumn<>(name);column.setCellValueFactory(data->new javafx.beans.property.SimpleStringProperty(data.getValue().getOrDefault(name,"")));column.setPrefWidth(150);t.getColumns().add(column);}JsonNode rows=response.path("results");if(rows.isArray())for(JsonNode row:rows){Map<String,String> values=new LinkedHashMap<>();if(row.isObject())row.fields().forEachRemaining(e->values.put(e.getKey(),e.getValue().isNull()?"null":e.getValue().asText(e.getValue().toString())));t.getItems().add(values);}}
 private void showUnavailable(String title,String text){VBox p=page(title,"Backend data is shown only when an existing API route provides it.");VBox c=new VBox(12);c.getStyleClass().add("card");Label msg=new Label(text);msg.setWrapText(true);msg.getStyleClass().add("muted");c.getChildren().addAll(new Label("Unavailable"),msg);p.getChildren().add(c);content.getChildren().setAll(p);}
 private void showHistory(){VBox p=page("Query History","Queries run during this application session.");ListView<QueryRecord> list=new ListView<>(history);TextArea sql=new TextArea();sql.setEditable(false);sql.setPromptText("Select a query to inspect its SQL");Label info=new Label("Question | Status | Duration | Timestamp");Button clear=new Button("Clear History");clear.getStyleClass().add("button secondary");clear.setOnAction(e->history.clear());list.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null){sql.setText(b.sql().isBlank()?"No SQL returned":b.sql());info.setText(b.status()+" | "+b.elapsed()+" | "+b.timestamp());}});SplitPane split=new SplitPane(list,new VBox(10,info,sql));VBox.setVgrow(split,Priority.ALWAYS);p.getChildren().addAll(clear,split);content.getChildren().setAll(p);}
 private void showDataSources(){VBox p=page("Data Sources","Database and dataset replacement are local future integrations.");VBox db=new VBox(12);db.getStyleClass().add("card");db.getChildren().addAll(new Label("Database"),new Label("Current backend database details are not exposed by the API."),new Label(databaseSummary));Button replaceDb=new Button("Replace Database");replaceDb.setOnAction(e->databaseDialog());db.getChildren().add(replaceDb);VBox ds=new VBox(12);ds.getStyleClass().add("card");Label chosen=new Label("Current Dataset: "+selectedDataset);Button replaceDs=new Button("Replace Dataset");replaceDs.setOnAction(e->{FileChooser fc=new FileChooser();fc.setTitle("Choose dataset");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("Supported datasets","*.csv","*.json","*.xlsx"));File f=fc.showOpenDialog(root.getScene().getWindow());if(f!=null){selectedDataset=f.getName();chosen.setText("Selected Dataset: "+selectedDataset+" | Ready for future backend integration");new Alert(Alert.AlertType.INFORMATION,"Dataset selected successfully. Dataset ingestion will be connected to the backend in a future version.").showAndWait();}});ds.getChildren().addAll(new Label("Dataset"),chosen,replaceDs);p.getChildren().addAll(db,ds);content.getChildren().setAll(p);}
 private void databaseDialog(){Dialog<Void>d=new Dialog<>();d.setTitle("Replace Database (local only)");ButtonType save=new ButtonType("Save locally",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(save,ButtonType.CANCEL);GridPane g=new GridPane();g.setHgap(10);g.setVgap(10);String[] names={"Database Type","Host","Port","Database Name","Username","Password"};TextField[] fields=new TextField[6];for(int i=0;i<names.length;i++){g.add(new Label(names[i]),0,i);fields[i]=i==5?new PasswordField():new TextField();g.add(fields[i],1,i);}fields[0].setText("PostgreSQL");fields[1].setText("localhost");fields[2].setText("5432");Button test=new Button("Test Connection");test.setOnAction(e->new Alert(Alert.AlertType.INFORMATION,"Dynamic database switching is not supported by the backend. No connection was attempted.").showAndWait());g.add(test,1,6);d.getDialogPane().setContent(g);d.setResultConverter(b->{if(b==save){databaseSummary="Local configuration saved for "+fields[0].getText()+" at "+fields[1].getText()+":"+fields[2].getText()+" / "+fields[3].getText();new Alert(Alert.AlertType.INFORMATION,"Database configuration saved locally. Dynamic database switching will be connected to the backend in a future version.").showAndWait();showDataSources();}return null;});d.showAndWait();}
 private void showSettings(){VBox p=page("Settings","Configure and test the FastAPI backend connection.");VBox c=new VBox(12);c.getStyleClass().add("card");TextField url=new TextField(ConfigurationService.getBackendUrl());url.setPromptText("http://127.0.0.1:8000");Label result=new Label("Not tested");Button test=new Button("Test Backend");test.setOnAction(e->{try{ConfigurationService.setBackendUrl(url.getText());result.setText("Testing...");test.setDisable(true);Task<JsonNode> task=new Task<>(){protected JsonNode call()throws Exception{return api.get("/");}};task.setOnSucceeded(ev->{test.setDisable(false);result.setText("* Backend Connected | "+task.getValue().path("message").asText("GET / responded"));result.setStyle("-fx-text-fill:#22C55E;");refreshBackendStatus();});task.setOnFailed(ev->{test.setDisable(false);result.setText("* Backend Unavailable | "+message(task.getException()));result.setStyle("-fx-text-fill:#EF4444;");refreshBackendStatus();});Thread t=new Thread(task,"backend-health-check");t.setDaemon(true);t.start();}catch(Exception ex){result.setText("Invalid backend URL: "+message(ex));}});c.getChildren().addAll(new Label("Backend URL"),url,test,result,new Label("Health check uses the real GET / endpoint."));p.getChildren().add(c);content.getChildren().setAll(p);}
 private void runTask(CallableTask call,java.util.function.Consumer<JsonNode> success,java.util.function.Consumer<Throwable> failure){Task<JsonNode> task=new Task<>(){protected JsonNode call()throws Exception{return call.run();}};task.setOnSucceeded(e->success.accept(task.getValue()));task.setOnFailed(e->failure.accept(task.getException()));Thread t=new Thread(task,"backend-request");t.setDaemon(true);t.start();}
 @FunctionalInterface private interface CallableTask{JsonNode run()throws Exception;} private String message(Throwable t){return t==null?"Unknown error":(t.getMessage()==null?t.getClass().getSimpleName():t.getMessage());}
 public static void main(String[] args){launch(args);}
}